class MyCalendar {
    private final TreeMap<Integer,Integer> bookings=new TreeMap<>();
    public MyCalendar(){
    }
    public boolean book(int startTime,int endTime){
        Map.Entry<Integer,Integer> previous=bookings.floorEntry(startTime),next=bookings.ceilingEntry(startTime);
        if(previous!=null&&previous.getValue()>startTime||next!=null&&next.getKey()<endTime)return false;
        bookings.put(startTime,endTime);
        return true;
    }
}

code.kotlin:
class MyCalendar {
    private val bookings=java.util.TreeMap<Int,Int>();
    fun book(startTime:Int,endTime:Int):Boolean{
        val previous=bookings.floorEntry(startTime);
        val next=bookings.ceilingEntry(startTime);
        if(previous!=null&&previous.value>startTime||next!=null&&next.key<endTime)return false;
        bookings[startTime]=endTime;
        return true
    }
}

